import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.PriorityQueue;

class Solution {
    public int shortestPathWithHops(int n, int[][] edges, int s, int d, int k) {
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
        for (int[] e : edges) {
            graph.get(e[0]).add(new int[]{e[1], e[2]});
            graph.get(e[1]).add(new int[]{e[0], e[2]});
        }
        int[][] dist = new int[n][k + 1];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        dist[s][k] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        pq.offer(new int[]{0, s, k});
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int cost = top[0], u = top[1], hops = top[2];
            if (u == d) return cost;
            if (cost > dist[u][hops]) continue;
            for (int[] next : graph.get(u)) {
                int v = next[0], w = next[1];
                if (cost + w < dist[v][hops]) {
                    dist[v][hops] = cost + w;
                    pq.offer(new int[]{dist[v][hops], v, hops});
                }
                if (hops > 0 && cost < dist[v][hops - 1]) {
                    dist[v][hops - 1] = cost;
                    pq.offer(new int[]{dist[v][hops - 1], v, hops - 1});
                }
            }
        }
        return -1;
    }
}

var shortestPathWithHops = function(n, edges, s, d, k) {
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        graph[u].push([v, w]);
        graph[v].push([u, w]);
    }
    const dist = Array.from({ length: n }, () => new Array(k + 1).fill(Infinity));
    dist[s][k] = 0;
    const pq = [[0, s, k]];
    while (pq.length > 0) {
        pq.sort((a, b) => a[0] - b[0]);
        const [cost, u, hops] = pq.shift();
        if (u === d) return cost;
        if (cost > dist[u][hops]) continue;
        for (const [v, w] of graph[u]) {
            if (cost + w < dist[v][hops]) {
                dist[v][hops] = cost + w;
                pq.push([dist[v][hops], v, hops]);
            }
            if (hops > 0 && cost < dist[v][hops - 1]) {
                dist[v][hops - 1] = cost;
                pq.push([dist[v][hops - 1], v, hops - 1]);
            }
        }
    }
    return -1;
};
